children.text:
.inline {
  display: inline;
  color: transparent;
  font: 10px Ahem;
  line-height: 25px;
}

.container {
  border: 1px solid;
  position: relative;
  width: 100px;
  height: 100px;
  display: inline-block;
  margin-left: 50px;
  margin-bottom: 50px;
}

.abs {
  width: 50px;
  height: 50px;
  position: absolute;
  background: purple;
}

.vertRL {
  writing-mode: vertical-rl;
}

.vertLR {
  writing-mode: vertical-lr;
}
